_5.styles:
/* Custom Utilities for this avant-garde look */
        .glass-panel {
            background: rgba(242, 239, 233, 0.7);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border: 1px solid rgba(255, 255, 255, 0.3);
        }

        .soft-shadow {
            box-shadow: 0px 4px 30px rgba(30, 15, 11, 0.08);
        }

        .floating-element {
            animation: float 6s ease-in-out infinite;
        }

        @keyframes float {
            0% { transform: translateY(0px); }
            50% { transform: translateY(-10px); }
            100% { transform: translateY(0px); }
        }

        .offset-border-card {
            position: relative;
        }

        .offset-border-card::before {
            content: '';
            position: absolute;
            top: 10px;
            left: 10px;
            right: -10px;
            bottom: -10px;
            border: 1px solid var(--tw-colors-outline-variant);
            border-radius: var(--tw-border-radius-xl);
            z-index: -1;
            transition: all 0.3s ease;
        }

        .offset-border-card:hover::before {
            top: 15px;
            left: 15px;
            right: -15px;
            bottom: -15px;
        }

